def objects(g):
    seen=set();objs={}
    from collections import deque
    for r in range(len(g)):
        for c in range(len(g[0])):
            v=g[r][c]
            if v and v not in objs:
                q=deque([(r,c)]);cells=set()
                while q:
                    a,b=q.popleft()
                    if (a,b) in cells or g[a][b]!=v: continue
                    cells.add((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<len(g) and 0<=nb<len(g[0]): q.append((na,nb))
                objs[v]=cells
    return objs

def transform(g):
    objs=objects(g)
    h=len(g);w=len(g[0])
    r8=min(r for r,c in objs[8])
    res=[[0]*w for _ in range(h)]
    for v,cells in objs.items():
        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        rows={}
        for r,c in cells: rows.setdefault(r-r0,[]).append(c-c0)
        dr=r8-r0
        nrows=sorted(rows)
        bw=max(c for r,c in cells)-c0+1
        for i,rr in enumerate(nrows):
            cs=sorted(rows[rr])
            # center the top row within bbox width if it has <bw cells? observed: top row pair centered
            out_cs=cs
            if rr==nrows[0] and len(cs)<bw:
                m=len(cs); off=(bw-m)//2
                out_cs=list(range(off,off+m))
            for j,c in enumerate(out_cs):
                nr=r0+dr+rr
                if 0<=nr<h and 0<=c0+c<w: res[nr][c0+c]=v
    return res

